   183→#[cfg(test)]
   184→mod tests {
   185→    use super::*;
   186→    use crate::test_utils::test_spec;
   187→    use bls::Hash256;
   188→    use std::sync::Arc;
   189→    use types::{Epoch, MainnetEthSpec};
   190→
   191→    type E = MainnetEthSpec;
   192→
   193→    fn get_blob_sidecar(slot: u64, proposer_index: u64, index: u64) -> Arc<BlobSidecar<E>> {
   194→        let mut blob_sidecar = BlobSidecar::empty();
   195→        blob_sidecar.signed_block_header.message.slot = slot.into();
   196→        blob_sidecar.signed_block_header.message.proposer_index = proposer_index;
   197→        blob_sidecar.index = index;
   198→        Arc::new(blob_sidecar)
   199→    }
   200→
   201→    #[test]
   202→    fn pruning() {
   203→        let spec = Arc::new(test_spec::<E>());
   204→        let mut cache = ObservedDataSidecars::<BlobSidecar<E>>::new(spec);
   205→
   206→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   207→        assert_eq!(cache.items.len(), 0, "no slots should be present");
   208→
   209→        // Slot 0, index 0
   210→        let proposer_index_a = 420;
   211→        let sidecar_a = get_blob_sidecar(0, proposer_index_a, 0);
   212→
   213→        assert_eq!(
   214→            cache.observe_sidecar(&sidecar_a),
   215→            Ok(false),
   216→            "can observe proposer, indicates proposer unobserved"
   217→        );
   218→
   219→        /*
   220→         * Preconditions.
   221→         */
   222→
   223→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   224→        assert_eq!(
   225→            cache.items.len(),
   226→            1,
   227→            "only one (validator_index, slot) tuple should be present"
   228→        );
   229→
   230→        let cached_blob_indices = cache
   231→            .items
   232→            .get(&ProposalKey::new(proposer_index_a, Slot::new(0)))
   233→            .expect("slot zero should be present");
   234→        assert_eq!(
   235→            cached_blob_indices.len(),
   236→            1,
   237→            "only one proposer should be present"
   238→        );
   239→
   240→        /*
   241→         * Check that a prune at the genesis slot does nothing.
   242→         */
   243→
   244→        cache.prune(Slot::new(0));
   245→
   246→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   247→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   248→        let cached_blob_indices = cache
   249→            .items
   250→            .get(&ProposalKey::new(proposer_index_a, Slot::new(0)))
   251→            .expect("slot zero should be present");
   252→        assert_eq!(
   253→            cached_blob_indices.len(),
   254→            1,
   255→            "only one proposer should be present"
   256→        );
   257→
   258→        /*
   259→         * Check that a prune empties the cache
   260→         */
   261→
   262→        cache.prune(E::slots_per_epoch().into());
   263→        assert_eq!(
   264→            cache.finalized_slot,
   265→            Slot::from(E::slots_per_epoch()),
   266→            "finalized slot is updated"
   267→        );
   268→        assert_eq!(cache.items.len(), 0, "no items left");
   269→
   270→        /*
   271→         * Check that we can't insert a finalized sidecar
   272→         */
   273→
   274→        // First slot of finalized epoch
   275→        let block_b = get_blob_sidecar(E::slots_per_epoch(), 419, 0);
   276→
   277→        assert_eq!(
   278→            cache.observe_sidecar(&block_b),
   279→            Err(Error::FinalizedDataSidecar {
   280→                slot: E::slots_per_epoch().into(),
   281→                finalized_slot: E::slots_per_epoch().into(),
   282→            }),
   283→            "cant insert finalized sidecar"
   284→        );
   285→
   286→        assert_eq!(cache.items.len(), 0, "sidecar was not added");
   287→
   288→        /*
   289→         * Check that we _can_ insert a non-finalized block
   290→         */
   291→
   292→        let three_epochs = E::slots_per_epoch() * 3;
   293→
   294→        // First slot of finalized epoch
   295→        let proposer_index_b = 421;
   296→        let block_b = get_blob_sidecar(three_epochs, proposer_index_b, 0);
   297→
   298→        assert_eq!(
   299→            cache.observe_sidecar(&block_b),
   300→            Ok(false),
   301→            "can insert non-finalized block"
   302→        );
   303→
   304→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   305→        let cached_blob_indices = cache
   306→            .items
   307→            .get(&ProposalKey::new(proposer_index_b, Slot::new(three_epochs)))
   308→            .expect("the three epochs slot should be present");
   309→        assert_eq!(
   310→            cached_blob_indices.len(),
   311→            1,
   312→            "only one proposer should be present"
   313→        );
   314→
   315→        /*
   316→         * Check that a prune doesnt wipe later blocks
   317→         */
   318→
   319→        let two_epochs = E::slots_per_epoch() * 2;
   320→        cache.prune(two_epochs.into());
   321→
   322→        assert_eq!(
   323→            cache.finalized_slot,
   324→            Slot::from(two_epochs),
   325→            "finalized slot is updated"
   326→        );
   327→
   328→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   329→        let cached_blob_indices = cache
   330→            .items
   331→            .get(&ProposalKey::new(proposer_index_b, Slot::new(three_epochs)))
   332→            .expect("the three epochs slot should be present");
   333→        assert_eq!(
   334→            cached_blob_indices.len(),
   335→            1,
   336→            "only one proposer should be present"
   337→        );
   338→    }
   339→
   340→    #[test]
   341→    fn simple_observations() {
   342→        let spec = Arc::new(test_spec::<E>());
   343→        let mut cache = ObservedDataSidecars::<BlobSidecar<E>>::new(spec.clone());
   344→
   345→        // Slot 0, index 0
   346→        let proposer_index_a = 420;
   347→        let sidecar_a = get_blob_sidecar(0, proposer_index_a, 0);
   348→
   349→        assert_eq!(
   350→            cache.proposer_is_known(&sidecar_a),
   351→            Ok(false),
   352→            "no observation in empty cache"
   353→        );
   354→
   355→        assert_eq!(
   356→            cache.observe_sidecar(&sidecar_a),
   357→            Ok(false),
   358→            "can observe proposer, indicates proposer unobserved"
   359→        );
   360→
   361→        assert_eq!(
   362→            cache.proposer_is_known(&sidecar_a),
   363→            Ok(true),
   364→            "observed block is indicated as true"
   365→        );
   366→
   367→        assert_eq!(
   368→            cache.observe_sidecar(&sidecar_a),
   369→            Ok(true),
   370→            "observing again indicates true"
   371→        );
   372→
   373→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   374→        assert_eq!(cache.items.len(), 1, "only one slot should be present");
   375→        let cached_blob_indices = cache
   376→            .items
   377→            .get(&ProposalKey::new(proposer_index_a, Slot::new(0)))
   378→            .expect("slot zero should be present");
   379→        assert_eq!(
   380→            cached_blob_indices.len(),
   381→            1,
   382→            "only one proposer should be present"
   383→        );
   384→
   385→        // Slot 1, proposer 0
   386→
   387→        let proposer_index_b = 421;
   388→        let sidecar_b = get_blob_sidecar(1, proposer_index_b, 0);
   389→
   390→        assert_eq!(
   391→            cache.proposer_is_known(&sidecar_b),
   392→            Ok(false),
   393→            "no observation for new slot"
   394→        );
   395→        assert_eq!(
   396→            cache.observe_sidecar(&sidecar_b),
   397→            Ok(false),
   398→            "can observe proposer for new slot, indicates proposer unobserved"
   399→        );
   400→        assert_eq!(
   401→            cache.proposer_is_known(&sidecar_b),
   402→            Ok(true),
   403→            "observed block in slot 1 is indicated as true"
   404→        );
   405→        assert_eq!(
   406→            cache.observe_sidecar(&sidecar_b),
   407→            Ok(true),
   408→            "observing slot 1 again indicates true"
   409→        );
   410→
   411→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   412→        assert_eq!(cache.items.len(), 2, "two slots should be present");
   413→        let cached_blob_indices = cache
   414→            .items
   415→            .get(&ProposalKey::new(proposer_index_a, Slot::new(0)))
   416→            .expect("slot zero should be present");
   417→        assert_eq!(
   418→            cached_blob_indices.len(),
   419→            1,
   420→            "only one proposer should be present in slot 0"
   421→        );
   422→        let cached_blob_indices = cache
   423→            .items
   424→            .get(&ProposalKey::new(proposer_index_b, Slot::new(1)))
   425→            .expect("slot zero should be present");
   426→        assert_eq!(
   427→            cached_blob_indices.len(),
   428→            1,
   429→            "only one proposer should be present in slot 1"
   430→        );
   431→
   432→        // Slot 0, index 1
   433→        let sidecar_c = get_blob_sidecar(0, proposer_index_a, 1);
   434→
   435→        assert_eq!(
   436→            cache.proposer_is_known(&sidecar_c),
   437→            Ok(false),
   438→            "no observation for new index"
   439→        );
   440→        assert_eq!(
   441→            cache.observe_sidecar(&sidecar_c),
   442→            Ok(false),
   443→            "can observe new index, indicates sidecar unobserved for new index"
   444→        );
   445→        assert_eq!(
   446→            cache.proposer_is_known(&sidecar_c),
   447→            Ok(true),
   448→            "observed new sidecar is indicated as true"
   449→        );
   450→        assert_eq!(
   451→            cache.observe_sidecar(&sidecar_c),
   452→            Ok(true),
   453→            "observing new sidecar again indicates true"
   454→        );
   455→
   456→        assert_eq!(cache.finalized_slot, 0, "finalized slot is zero");
   457→        assert_eq!(cache.items.len(), 2, "two slots should be present");
   458→        let cached_blob_indices = cache
   459→            .items
   460→            .get(&ProposalKey::new(proposer_index_a, Slot::new(0)))
   461→            .expect("slot zero should be present");
   462→        assert_eq!(
   463→            cached_blob_indices.len(),
   464→            2,
   465→            "two blob indices should be present in slot 0"
   466→        );
   467→
   468→        // Create a sidecar sharing slot and proposer but with a different block root.
   469→        let mut sidecar_d: BlobSidecar<E> = BlobSidecar {
   470→            index: sidecar_c.index,
   471→            blob: sidecar_c.blob.clone(),
   472→            kzg_commitment: sidecar_c.kzg_commitment,
