   475→            kzg_commitment_inclusion_proof: sidecar_c.kzg_commitment_inclusion_proof.clone(),
   476→        };
   477→        sidecar_d.signed_block_header.message.body_root = Hash256::repeat_byte(7);
   478→        assert_eq!(
   479→            cache.proposer_is_known(&sidecar_d),
